import numpy as np
t=df['t'].values;A=df['A'].values;y=df['dA_dt'].values
tb={'1':np.ones_like(t),'1/t':1/t,'t':t,'t2':t**2,'exp':np.exp(-t),'sin':np.sin(t),'cos':np.cos(t),'lnt':np.log(t)}
def test(powers,tbs):
    cols=[A**p*tb[k] for p in powers for k in tbs]
    X=np.column_stack(cols)
    c,_,_,_=np.linalg.lstsq(X,y,rcond=None)
    r=X@c-y
    return np.mean(r**2)/np.var(y)
base=['1','1/t','t','t2','exp','lnt']
for pw in [[0,1],[0,2],[0,1,2],[0,1,2,3]]:
    print(pw, test(pw,base), test(pw,['1','1/t','t','exp']), test(pw,['1','t','exp','sin','cos']))
